/**
 * Authentication middleware for PostgreSQL mode.
 * Validates HS256 JWT tokens generated by Decyra's local auth.
 */

import { createMiddleware } from '@tanstack/react-start';
import { getRequest } from '@tanstack/react-start/server';
import { verifyJwt } from '@/integrations/database/local-auth.server';

export interface AuthContext {
  userId: string;
  claims: Record<string, unknown>;
  isDatabaseLocal: true;
}

// Alias for backward compatibility if referenced
export type FlexibleAuthContext = AuthContext;

export const requireAuth = createMiddleware({ type: 'function' }).server(
  async ({ next }): Promise<any> => {
    const request = getRequest();

    if (!request?.headers) {
      throw new Error('Unauthorized: No request headers available');
    }

    const authHeader = request.headers.get('authorization');

    if (!authHeader) {
      throw new Error('Unauthorized: No authorization header provided');
    }

    if (!authHeader.startsWith('Bearer ')) {
      throw new Error('Unauthorized: Only Bearer tokens are supported');
    }

    const token = authHeader.replace('Bearer ', '').trim();
    if (!token) {
      throw new Error('Unauthorized: No token provided');
    }

    try {
      const payload = verifyJwt(token);

      if (!payload) {
        throw new Error('Invalid or expired token');
      }

      const userId = (payload.sub as string) || (payload.user_id as string);
      if (!userId) {
        throw new Error('No user ID found in token');
      }

      const ctx: AuthContext = {
        userId,
        claims: payload,
        isDatabaseLocal: true,
      };

      return next({ context: ctx });
    } catch (error: any) {
      console.error('Token validation failed:', error?.message ?? error);
      throw new Error('Unauthorized: Invalid token');
    }
  }
);

// Alias so existing decyra.functions imports work seamlessly
export const requireFlexibleAuth = requireAuth;
